public final class V3818 {

    private static final int VERSION = MCVersions.V24W07A + 1;

    private static final String[] BANNER_COLOURS = new String[] {
            "white",
            "orange",
            "magenta",
            "light_blue",
            "yellow",
            "lime",
            "pink",
            "gray",
            "light_gray",
            "cyan",
